-- Production SHOW CREATE TABLE snapshot (2026-09-04), CODECs and index_granularity stripped.
-- Harness fixture only -- not a migration, never apply to a real ClickHouse.

CREATE TABLE IF NOT EXISTS corpscout.company_identifier (
    `issuer_scheme` LowCardinality(String),
    `issuer_id` String,
    `country_code` LowCardinality(String),
    `company_id` String,
    `match_method` LowCardinality(String),
    `match_confidence` LowCardinality(String),
    `registration_authority_id` LowCardinality(String),
    `registered_as_raw` String,
    `company_id_normalized` String,
    `entity_status` LowCardinality(String),
    `registration_status` LowCardinality(String),
    `is_current` UInt8,
    `successor_issuer_id` String,
    `first_seen_date` Date,
    `last_seen_date` Date,
    `source_run_id` String,
    `resolved_at` DateTime64(3, 'UTC')
) ENGINE = MergeTree ORDER BY (issuer_scheme, issuer_id, country_code, company_id);

CREATE TABLE IF NOT EXISTS corpscout.esef_document_company_information (
    `source_document_id` String,
    `source_record_uid` String DEFAULT lower(hex(SHA256(concat('company-source-record-v1\nfile\nesef_report_package\n', lowerUTF8(toString(package_sha256)))))),
    `package_sha256` String,
    `lei` String,
    `country_iso2` LowCardinality(String),
    `company_id` String,
    `period_end` String,
    `fiscal_year` UInt16,
    `extraction_status` LowCardinality(String),
    `company_description` String,
    `description_language` LowCardinality(String),
    `description_confidence` Float64,
    `description_evidence_ids_json` String,
    `people_json` String,
    `products_and_services_json` String,
    `customer_markets_json` String,
    `operating_geographies_json` String,
    `business_segments_json` String,
    `material_group_relationships_json` String,
    `enrichment_artifact_object_key` String,
    `input_artifact_object_key` String,
    `llm_request_object_key` String,
    `llm_request_sha256` String,
    `llm_response_text` String,
    `llm_response_sha256` String,
    `model_provider` LowCardinality(String),
    `model_name` String,
    `prompt_version` String,
    `prompt_tokens` UInt64,
    `completion_tokens` UInt64,
    `input_character_count` UInt64,
    `source_run_id` String,
    `extracted_at` String,
    `resolved_at` DateTime64(3) DEFAULT now64(3)
) ENGINE = MergeTree ORDER BY (source_document_id, model_provider, model_name, prompt_version);

CREATE TABLE IF NOT EXISTS corpscout.se_company_info_enrichment_observation (
    `suggestion_id` UUID,
    `company_id` String,
    `input_hash` FixedString(64),
    `suggestion` String,
    `raw_response` String,
    `model_provider` LowCardinality(String),
    `model_name` String,
    `prompt_version` String,
    `prompt_tokens` UInt32,
    `completion_tokens` UInt32,
    `source_run_id` String,
    `created_at` DateTime64(3, 'UTC')
) ENGINE = MergeTree ORDER BY (company_id, input_hash, created_at);

CREATE TABLE IF NOT EXISTS corpscout.se_ratsit_company (
    `company_id` String,
    `result_sha256` FixedString(64),
    `normalizer_version` LowCardinality(String),
    `schema_version` UInt16,
    `parser_version` LowCardinality(String),
    `requested_url` String,
    `source_url` String,
    `result_bucket` LowCardinality(String),
    `result_object_key` String,
    `name` String,
    `organization_number` String,
    `legal_form` Nullable(String),
    `status` Nullable(String),
    `address_street` Nullable(String),
    `address_postal_code` Nullable(String),
    `address_locality` Nullable(String),
    `address_county` Nullable(String),
    `business_description` Nullable(String),
    `latitude` Nullable(Float64),
    `longitude` Nullable(Float64),
    `source_date_modified` Nullable(Date32),
    `industry_code_count` UInt16,
    `summary_count` UInt16,
    `responsible_people_count` UInt16,
    `establishment_count` UInt16,
    `financial_report_count` UInt16,
    `financial_period_count` UInt16,
    `people_at_address_count` UInt16,
    `normalized_at` DateTime64(6, 'UTC')
) ENGINE = ReplacingMergeTree(normalized_at) ORDER BY (company_id, result_sha256, normalizer_version);

CREATE TABLE IF NOT EXISTS corpscout.text_translations (
    `source_table` LowCardinality(String),
    `source_column` LowCardinality(String),
    `source_text_hash` UInt64,
    `source_lang` LowCardinality(String),
    `target_lang` LowCardinality(String),
    `translated_text` String,
    `provider` LowCardinality(String),
    `model` LowCardinality(String),
    `version` UInt64
) ENGINE = ReplacingMergeTree(version) ORDER BY (source_table, source_column, source_text_hash, source_lang, target_lang);

CREATE TABLE IF NOT EXISTS corpscout.wikidata_companies (
    `wikidata_id` String,
    `wikidata_url` String,
    `name` String,
    `name_normalized` String,
    `company_description` Nullable(String),
    `official_name` Nullable(String),
    `headquarters_wikidata_id` Nullable(String),
    `headquarters_label` Nullable(String),
    `headquarters_country_wikidata_id` Nullable(String),
    `headquarters_country_label` Nullable(String),
    `headquarters_country_iso2` Nullable(String),
    `country_resolution_method` Nullable(String),
    `country_resolution_confidence` Nullable(String),
    `inception_date` Nullable(Date),
    `legal_form_wikidata_id` Nullable(String),
    `legal_form_label` Nullable(String),
    `employee_count` Nullable(UInt64),
    `employee_count_point_in_time` Nullable(Date),
    `logo_image` Nullable(String),
    `logo_image_url` Nullable(String),
    `industry_wikidata_id` Nullable(String),
    `industry_label` Nullable(String),
    `has_current_listing` UInt8,
    `listing_count` UInt64,
    `source_system` LowCardinality(String),
    `source_run_id` String,
    `source_record_id` String,
    `source_payload_hash` FixedString(64),
    `retrieved_at` DateTime64(3, 'UTC'),
    `resolved_at` DateTime64(3, 'UTC')
) ENGINE = ReplacingMergeTree(resolved_at) ORDER BY (wikidata_id);

CREATE TABLE IF NOT EXISTS corpscout.wikidata_company_identifiers (
    `wikidata_id` String,
    `identifier_type` LowCardinality(String),
    `wikidata_property_id` LowCardinality(String),
    `identifier_value` String,
    `identifier_scope` Nullable(String),
    `is_primary` UInt8,
    `source_system` LowCardinality(String),
    `source_run_id` String,
    `source_record_id` String,
    `source_payload_hash` FixedString(64),
    `retrieved_at` DateTime64(3, 'UTC'),
    `resolved_at` DateTime64(3, 'UTC')
) ENGINE = ReplacingMergeTree(resolved_at) ORDER BY (identifier_type, identifier_value, wikidata_id);
